document.addEventListener("DOMContentLoaded",()=>{let a=new Date().toISOString().split("T")[0],e=document.getElementById("tanggalAwal"),t=document.getElementById("tanggalAkhir");e.value=a,t.value=a,t.setAttribute("max",a)});async function cari(){let n=document.getElementById("departemen").value;if(n==="")return Swal.fire({icon:"warning",title:"Oops.",text:"Mohon pilih Bidang / Departemen terlebih dahulu di panel Jadwal."}),!1;let a=document.getElementById("tanggalAwal").value,e=document.getElementById("tanggalAkhir").value,t=document.getElementById("listKehadiran");t.innerHTML='<div class="text-center py-8 text-primary"><span class="loading loading-spinner loading-md"></span> Memuat data...</div>';try{const s=await fetch(`/api/presensi/attendance?dep=${n}&start=${a}&end=${e}`,{method:"GET"});if(s.ok){const l=await s.json();listKehadiran(l.data)}else console.error("Error fetching data:",s.status),t.innerHTML='<div class="text-center text-error py-4">Gagal memuat data.</div>'}catch(s){console.error("Error:",s),t.innerHTML='<div class="text-center text-error py-4">Terjadi kesalahan koneksi.</div>'}}function listKehadiran(n){let a=document.getElementById("listKehadiran");if(!n||n.length===0){a.innerHTML=`
            <div class="text-center py-10 bg-base-200/50 rounded-xl border border-base-200 border-dashed">
                <i class="fas fa-inbox text-3xl text-base-content/30 mb-3 block"></i>
                <p class="text-sm font-medium text-base-content/60">Tidak ada data kehadiran pada rentang tanggal tersebut.</p>
            </div>`;return}a.innerHTML="";for(let e of n){let t="",s="";e.absen.cekIn?e.absen.statusIn==="Masuk Terlambat"?t=`<span>Masuk: <strong class="text-error">${e.absen.cekIn}</strong></span>
                     <span class="text-error text-xs font-semibold">(${e.absen.keteranganIn})</span>`:(e.absen.statusIn==="Masuk Tepat Waktu"||e.absen.statusIn==="Masuk Cepat")&&(t=`<span>Masuk: <strong class="text-base-content">${e.absen.cekIn}</strong></span>
                     <span class="text-success text-xs font-semibold">(${e.absen.statusIn})</span>`):t=`<span>Masuk: <strong class="text-error">--:--</strong></span>
                     <span class="text-error text-xs font-semibold">(Tidak Absen)</span>`,e.absen.cekOut?e.absen.statusOut==="Pulang Cepat"?s=`<span>Pulang: <strong class="text-error">${e.absen.cekOut}</strong></span>
                      <span class="text-error text-xs font-semibold">(${e.absen.keteranganOut})</span>`:(e.absen.statusOut==="Pulang Tepat Waktu"||e.absen.statusOut==="Pulang Terlambat")&&(s=`<span>Pulang: <strong class="text-base-content">${e.absen.cekOut}</strong></span>
                      <span class="text-success text-xs font-semibold">(${e.absen.statusOut})</span>`):s=`<span>Pulang: <strong class="text-error">--:--</strong></span>
                      <span class="text-error text-xs font-semibold">(Tidak Absen)</span>`;let l=`
        <div class="card bg-base-100 border border-base-200 shadow-sm hover:border-primary/50 transition-colors">
            <div class="card-body p-4 flex flex-col lg:flex-row lg:items-center justify-between gap-4">

                <!-- Info Pegawai & Jadwal -->
                <div class="flex-1">
                    <div class="flex items-center gap-2 mb-2">
                        <span class="text-sm font-semibold text-base-content/70">
                            <i class="fas fa-calendar-alt mr-1"></i> ${e.date}
                        </span>
                        <span class="badge badge-primary badge-sm shadow-sm">${e.dnsType?.type||"-"}</span>
                    </div>
                    
                    <h3 class="text-lg font-bold text-base-content flex items-center gap-2 mb-2">
                        <i class="fas fa-user-circle text-base-content/40 text-xl"></i> ${e.user?.nama||"-"}
                    </h3>
                    
                    <div class="space-y-1 mt-2">
                        <p class="text-xs text-base-content/60 flex items-start gap-2">
                            <i class="fas fa-location-dot mt-0.5 text-center w-4"></i> 
                            <span><strong class="font-medium">Lokasi Masuk:</strong> ${e.absen.loactionIn||"-"}</span>
                        </p>
                        <p class="text-xs text-base-content/60 flex items-start gap-2">
                            <i class="fas fa-location-dot mt-0.5 text-center w-4"></i> 
                            <span><strong class="font-medium">Lokasi Pulang:</strong> ${e.absen.loactionOut||"-"}</span>
                        </p>
                    </div>
                </div>

                <!-- Status Check In / Check Out -->
                <div class="flex flex-col sm:flex-row gap-3 w-full lg:w-auto shrink-0 border-t lg:border-t-0 border-base-200 pt-3 lg:pt-0">
                    <div class="bg-base-200/50 rounded-lg p-3 flex flex-col justify-center min-w-[160px]">
                        <div class="flex items-center gap-2 text-sm text-base-content mb-1">
                            <i class="fas fa-sign-in-alt text-warning"></i>
                            ${t}
                        </div>
                    </div>
                    
                    <div class="bg-base-200/50 rounded-lg p-3 flex flex-col justify-center min-w-[160px]">
                        <div class="flex items-center gap-2 text-sm text-base-content mb-1">
                            <i class="fas fa-sign-out-alt text-success"></i>
                            ${s}
                        </div>
                    </div>
                </div>

            </div>
        </div>
        `;a.insertAdjacentHTML("beforeend",l)}}
